import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"WebDAV 模块","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/modules/webdav.md","filePath":"zh-Hans/deep-dive/modules/webdav.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/modules/webdav.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="webdav-模块" tabindex="-1">WebDAV 模块 <a class="header-anchor" href="#webdav-模块" aria-label="Permalink to “WebDAV 模块”">​</a></h1><p>WebDAV 模块注册 <code>webdav</code> 远端文件系统。它只使用 Sync Engine 注入的 <a href="./../request"><code>Request</code></a> 抽象实现<a href="./../file-system#统一键模式">统一文件系统键模式</a>，不依赖任何 WebDAV 客户端库。</p><h2 id="支持的后端" tabindex="-1">支持的后端 <a class="header-anchor" href="#支持的后端" aria-label="Permalink to “支持的后端”">​</a></h2><p>标准模式理论上可以配合任何支持 HTTP(S)、Basic 或 Digest (MD5) 认证、range <code>GET</code>、<code>PROPFIND</code>、<code>PUT</code>、<code>DELETE</code>、<code>MOVE</code> 和 <code>MKCOL</code> 的 WebDAV 服务工作。这包括基于以下项目的 WebDAV 安装：</p><ul><li>Nextcloud</li><li>ownCloud</li><li>Apache <code>mod_dav</code></li><li>Microsoft IIS WebDAV</li><li>InfiniCLOUD</li><li>Koofr WebDAV API</li><li>Synology WebDAV Server</li><li>Seafile 的 WebDAV 扩展</li><li>SabreDAV</li><li>Nutstore</li><li>AList、OpenList 和 Cloudreve 的 WebDAV 兼容层</li></ul><p>可选的分片上传模式要求 Nextcloud 的上传协议，不是标准 WebDAV。只在兼容的 Nextcloud 服务器上启用它。</p><h2 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to “认证”">​</a></h2><p>模块先发送 Basic 凭据。服务器以 <code>401</code> 和 Digest 挑战应答时，它切换到 Digest（带 <code>qop=auth</code> 的 MD5，或不带 <code>qop</code> 的旧式方案），并把挑战状态缓存在内存数据库中，以端点、用户名和密码为键。指名其他算法的挑战会被拒绝，模块继续发送 Basic 凭据。</p><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to “设置”">​</a></h2><p>模块注册这些设置：</p><ul><li><strong>Server URL</strong>：HTTP 或 HTTPS WebDAV 端点。无效 URL 和非 HTTP(S) 协议被拒绝；保存时移除尾部斜杠。</li><li><strong>Username</strong>：WebDAV 账户名，保存前去除首尾空格。</li><li><strong>Password</strong>：WebDAV 账户密码。Obsidian 把它保存在钥匙串中，而不是模块设置里。</li><li><strong>Base directory</strong>：成为仓库根目录的远端目录。<code>/</code> 使用端点根目录。值会被去除首尾空格并以尾部斜杠规范化。持久化的空值在模块构造时默认为 <code>&lt;仓库名&gt;/</code>。</li><li><strong>Use <code>Depth: infinity</code></strong>：用一个 <code>PROPFIND</code> 请求列出整棵目录树，而不是递归遍历单层深度响应。它可以加快远端发现，但一些服务器不支持它。启用<a href="./../asymmetric-storage">非对称存储</a>时它没有性能收益。</li><li><strong>Nextcloud-style chunked upload</strong>：通过 Nextcloud 的分片上传协议上传大的流式文件，而不是把整个文件缓冲在内存中。大多数 WebDAV 服务器不支持这种模式。</li><li><strong>File metadata</strong>：上传后通过 <code>PROPPATCH</code> 把文件元数据（例如创建时间）存为 JSON 编码的自定义属性 <code>se:meta</code>，并在 <code>PROPFIND</code> 时读回。只在服务器支持带自定义 dead property 的 <code>PROPPATCH</code> 时启用。</li></ul><h2 id="文件操作" tabindex="-1">文件操作 <a class="header-anchor" href="#文件操作" aria-label="Permalink to “文件操作”">​</a></h2><p><code>read()</code> 发送 <code>GET</code> 并返回响应字节。<code>write()</code> 发送 <code>PUT</code>，响应带有 <code>ETag</code> 头时返回它；否则立即调用 <code>stat()</code> 并返回得到的文件 UID。文件元数据启用且文件的 <code>meta</code> 非空时，<code>write()</code> 还会发送 <code>PROPPATCH</code> 请求，把元数据存为 JSON 编码的 <code>se:meta</code> 自定义属性。<code>PUT</code> 和 <code>PROPPATCH</code> 并发执行。</p><p><code>delete()</code> 发送 <code>DELETE</code>，把 HTTP <code>404</code> 视为已删除。<code>move()</code> 发送带 <code>Destination</code> 头的 <code>MOVE</code>。<code>mkdir()</code> 发送 <code>MKCOL</code>；递归创建按顺序创建祖先目录并忽略 HTTP <code>405</code>（表示目录已存在）。</p><p><code>stat()</code> 对目标发送 depth 为零的 <code>PROPFIND</code>。请求索取资源类型、修改时间、内容长度和 <code>ETag</code>；文件元数据启用时还索取 <code>se:meta</code>。文件 UID 优先用 <code>ETag</code>，否则用 <code>&lt;mtime&gt;~&lt;size&gt;</code>；文件夹没有 UID。<code>exists()</code> 使用相同的查询，HTTP <code>404</code> 返回 <code>false</code>。</p><p><code>PROPFIND</code> 响应分页通过 <code>Link: &lt;...&gt;; rel=&quot;next&quot;</code> 响应头支持。</p><h2 id="流式传输" tabindex="-1">流式传输 <a class="header-anchor" href="#流式传输" aria-label="Permalink to “流式传输”">​</a></h2><p><code>readStream()</code> 使用 range <code>GET</code> 请求，因为 <a href="./../request#限制"><code>Request</code> 无法暴露响应流</a>。它请求 2 MiB 的 range，同时在途请求最多八个，缓冲的分块最多八个，并按源顺序发出分块。只有流的消费者还能接收数据时才调度新请求。零字节文件返回一个关闭的流。</p><p>未启用分片上传时，<code>writeStream()</code> 在内存中收集完整的输入流，然后携带文件的 stat（含元数据）调用 <code>write()</code>。</p><p>启用 Nextcloud 风格分片上传时，它：</p><ol><li>在 Nextcloud 的上传端点下创建以 UUID 命名的上传集合。</li><li>把输入切成 5 MiB 的编号分块，最多三个并发上传。每个上传带 <code>Destination</code> 和 <code>OC-Total-Length</code> 头。</li><li>把生成的 <code>.file</code> 移动到目标位置。</li><li>返回 <code>ETag</code> 或 <code>OC-ETag</code>；两者都不存在时，调用 <code>stat()</code> 获取文件 UID。文件元数据启用时，<code>MOVE</code> 之后发送 <code>PROPPATCH</code> 存储 <code>se:meta</code>。</li></ol><p>失败时，模块等待进行中的上传完成并删除临时上传集合。</p><h2 id="基目录包装器" tabindex="-1">基目录包装器 <a class="header-anchor" href="#基目录包装器" aria-label="Permalink to “基目录包装器”">​</a></h2><p>WebDAV 使用共享的可导入 <a href="./../../development/file-system#prefixwrapper"><code>prefixWrapper</code></a> 把配置的基目录暴露为文件系统根。包装器链细节见<a href="./../file-system-wrappers">文件系统包装器</a>。</p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};